      teachingPoints: [
        'A logical fallacy is a flaw in reasoning that makes an argument invalid, unsound, or deceptive.',
        'An argument consists of premises (reasons) intended to support a conclusion.',
        'A valid argument has correct logical structure; a sound argument is valid AND has true premises. Fallacies can be formal (flawed deductive structure) or informal (flawed content, ambiguity, or relevance).',
      ],
      questions: [
        DailyLearningQuestion(
          prompt: 'What is a logical fallacy?',
          options: ['A flaw or error in reasoning that weakens or invalidates an argument', 'A factually true statement with no grammar errors', 'A mathematical calculation involving fractions', 'An insult delivered during an argument'],
          correctIndex: 0,
          explanation: 'A fallacy is an error in reasoning that renders an argument logically defective.',
        ),
        DailyLearningQuestion(
          prompt: 'In logic, what is a \'premise\'?',
          options: ['The final emotional conclusion', 'A proposition or statement offered as evidence or justification for a conclusion', 'The name of the philosopher speaking', 'A punctuation comma in a syllogism'],
          correctIndex: 1,
          explanation: 'Premises are the foundational evidence given to support a conclusion.',
        ),
        DailyLearningQuestion(
          prompt: 'What is a \'deductive\' argument considered when its structure guarantees the truth of the conclusion if premises are true?',
          options: ['Biased', 'Anecdotal', 'Valid', 'Hypothetical'],
          correctIndex: 2,
          explanation: 'Validity refers to formal structural correctness: true premises guarantee a true conclusion.',
