      teachingPoints: [
        'Appeal to ignorance asserts that a proposition must be true because there is no conclusive evidence disproving it, or false because there is no proof confirming it.',
        'Absence of evidence is not necessarily evidence of absence, especially when investigation is incomplete or methods are limited.',
        'In scientific inquiry and formal logic, the burden of proof rests on the claimant proposing an existence or effect, not on the skeptic to disprove it. A notable exception exists in legal systems: a defendant is presumed innocent until proven guilty, which is a procedural protection rather than an ontological proof.',
      ],
