    DailyLearningLesson(
      id: 'fallacies_17',
      title: 'Day 17: Fallacies of Composition and Division',
      teachingPoints: [
        'The Fallacy of Composition occurs when one assumes that because individual parts have a certain property, the whole entity composed of those parts must also share that property.',
        'The Fallacy of Division is the reverse: assuming that because the whole system has a property, each individual part must inherently possess it.',
        'Emergence in complex systems demonstrates that wholes often possess emergent properties that are absent in individual parts (e.g., water is wet, but single H2O molecules do not exhibit wetness). To dismantle these fallacies, analyze whether the property under discussion is distributive (applies to each part) or collective (applies only to the aggregate).',
      ],
