    DailyLearningLesson(
      id: 'fallacies_19',
      title: 'Day 19: Loaded Question (Complex Question / Plurium Interrogationum)',
      teachingPoints: [
        'A loaded question (or complex question) is a question that presupposes a controversial or unproven premise, forcing the respondent to tacitly endorse that premise regardless of whether they answer \'yes\' or \'no\'.',
        'The classic archetype is: \'Have you stopped beating your spouse?\' Either an answer of \'yes\' (admits having done it in the past) or \'no\' (admits to continuing) concedes the guilt.',
        'This rhetorical ambush is widely employed in hostile interrogations, sensationalist journalism, and debate cross-examinations to corner an opponent. The only effective defense is to reject the question\'s premise directly rather than selecting between the entrapping answers provided.',
      ],
      questions: [
        DailyLearningQuestion(
          prompt: 'What is a \'Loaded Question\' (Complex Question)?',
          options: ['A question that embeds an unverified, controversial assumption that is affirmed regardless of a yes or no answer', 'A question with many technical words', 'A question about heavy weights', 'An exam question worth many marks'],
          correctIndex: 0,
