      teachingPoints: [
        'Appeal to Tradition (Argumentum ad Antiquitatem) asserts that a policy, belief, or practice is correct, optimal, or moral simply because it has been done for a long time (\'We have always done it this way\').',
        'The twin opposite is Appeal to Novelty (Argumentum ad Novitatem), which claims that an idea, product, or method is superior merely because it is modern, fresh, or newly invented.',
        'Longevity indicates historical survival, but traditions often perpetuate outdated superstitions, injustices (e.g., slavery, bloodletting), and inefficiencies. Conversely, novelty brings change, but new things can be untested, buggy, or outright inferior. The age of an idea has zero bearing on its logical truth or practical effectiveness.',
