    DailyLearningLesson(
      id: 'fallacies_25',
      title: 'Day 25: Special Pleading',
      teachingPoints: [
        'Special Pleading is an informal fallacy that occurs when a person applies a general rule, standard, or principle to others while inventing an unjustified exception or exemption for themselves or their favored position.',
        'It is the intellectual equivalent of a double standard: \'The rules apply to everyone except me, because my situation is somehow uniquely exempt.\'',
        'In pseudo-science and paranormal claims, special pleading frequently appears as an excuse when an experiment fails: \'My psychic powers only work when skeptics are not radiating negative vibrational skepticism!\' To dismantle special pleading, demand the objective, principled criterion that justifies the alleged exception.',
