      teachingPoints: [
        'The Burden of Proof (Onus Probandi) is the fundamental epistemological obligation of the party proposing a claim to produce evidence supporting it.',
        'Shifting the Burden of Proof occurs when a claimant asserts an extraordinary or controversial position, and instead of providing evidence, demands that critics disprove it (\'You can\'t prove I\'m wrong, so I\'m right!\').',
        'Philosopher Christopher Hitchens formulated the famous maxim: \'What can be asserted without evidence can also be dismissed without evidence.\' In rational debate and scientific method, the default baseline is skepticism; the person introducing an assertion must supply verifiable evidence commensurate with the claim\'s scope.',
